import React, { useRef } from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

import "./MiniSlider.css";

//oto slide
function AutoPlayMethods() {
  let sliderRef = useRef(null);
  const play = () => {
    sliderRef.slickPlay();
  };
  const pause = () => {
    sliderRef.slickPause();
  };
}

//sağ buton
function ButtonRight(props){
  const{className, onClick} = props;
  return(
    <div
    className={`${className} btn`}
    onClick={onClick}
    >
    <img src="/src/components/assets/butonlar/button-right1.png"></img>
  </div>
  )
}

//sol buton
function ButtonLeft(props){
  const{className, onClick} = props;
  return(
    <div
    className={`${className} btn`}
    onClick={onClick}
    >
    <img src="../components/assets/butonlar/button-left1.png"></img>
  </div>
  )
}

function MiniSlider() {

  const settings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 6, //tek seferde gösterilen kart
    slidesToScroll: 1, //kaçar kaçar kayıyor
    autoplay: true,
    autoplaySpeed: 4000,
    nextArrow: <ButtonRight />,
    prevArrow: <ButtonLeft />
  };

  return (
    <div className="container">
      <Slider {...settings}>
        <div>
          <img src="../components/assets/logolar/brand_logos/1.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/2.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/3.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/8.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/9.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/15.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/16.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/17.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/18.webp" alt="logo1"/>
        
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/19.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/20.webp" alt="logo1"/>
        </div>
        <div>
        <img src="../components/assets/logolar/brand_logos/21.webp" alt="logo1"/>
        </div>
      </Slider>
    </div>
  );
}

export default MiniSlider;
